/**
 * Reinitializes a scheduled data workflow based on the current cron expression.
 *
 * This is needed in case an [updated](https://dev.wix.com/docs/api-reference/business-solutions/cms/operations/data-sync-jobs/update-data-sync-job) scheduled data workflow gets out of sync.
 * For example, if you update the cron expression, it may not initially run according to the new expression.
 * This reschedules it to run according to the new expression.
 *
 * Only applies to `enabled` scheduled data workflows.
 */
export function rescheduleScheduledDataWorkflow(
  payload: object
): RequestOptionsFactory<any> {
  function __rescheduleScheduledDataWorkflow({ host }: any) {
    const metadata = {
      entityFqdn: 'wix.data.sync.v1.jobs',
      method: 'POST' as any,
      methodFqn:
        'wix.hub.v1.DataMovementSchedulerService.RescheduleScheduledDataWorkflow',
      packageName: PACKAGE_NAME,
      migrationOptions: {
        optInTransformResponse: true,
      },
      url: resolveWixHubV1DataMovementSchedulerServiceUrl({
        protoPath:
          '/v1/scheduled-data-workflows/{scheduledDataWorkflowId}/reschedule',
        data: payload,
        host,
      }),
      data: payload,
      transformResponse: (payload: any) =>
        transformPaths(payload, [
          {
            transformFn: transformRESTTimestampToSDKTimestamp,
            paths: [{ path: 'nextExecutionDate' }],
          },
        ]),
    };

    return metadata;
  }

  return __rescheduleScheduledDataWorkflow;
}

